@BeforeClass
    public static void beforeClass() throws Exception {
        Executors.newSingleThreadExecutor().execute(new Runnable() {
            @Override
            public void run() {
                server.run();
            }
        });

        while (ConfigurationController.getInstance().getStatus() != ConfigurationController.STATUS_OK) {
            Thread.sleep(100);
        }

        ChannelController channelController = ChannelController.getInstance();
        EngineController engineController = ControllerFactory.getFactory().createEngineController();

        if (channelController.getChannelById(CHANNEL_ID) == null) {
            channelController.updateChannel(TestUtils.getChannel(CHANNEL_ID), ServerEventContext.SYSTEM_USER_EVENT_CONTEXT, true);

            if (channelController.getChannelById(CHANNEL_ID) == null) {
                throw new Exception("Failed to create channel");
            }
        }

        if (!engineController.isDeployed(CHANNEL_ID)) {
            Set<String> channelIds = new LinkedHashSet<String>();
            channelIds.add(CHANNEL_ID);
            engineController.deployChannels(channelIds, ServerEventContext.SYSTEM_USER_EVENT_CONTEXT, null, false);
            Thread.sleep(200);

            if (!engineController.isDeployed(CHANNEL_ID)) {
                throw new Exception("failed to deploy channel");
            }
        }
    }

