@Before
	public void init() {
		indices = new ArrayList[5];
		values = new ArrayList[5];
		indexHashMap = new HashMap <>();
		for (int i = 0; i < 5; i++) {
			indices[i] = new ArrayList <>();
			values[i] = new ArrayList <>();
			indices[i].add(i);
			indices[i].add(i + 1);
			indices[i].add(i + 2);
			values[i].add(1.0 * i);
			values[i].add(i * 2.);
			values[i].add(i * 3.);
			indexHashMap.put(i, Tuple2.of(indices[i], values[i]));
		}
	}

