		for (int i = 0; i < INSERT_COUNT; i++) {
			ClientTestModel model = new ClientTestModel();
			model.setAddress("SH-" + i);
			model.setLastChanged(new Timestamp(System.currentTimeMillis()));
			model.setQuantity(i%10);
			model.setType((short)(i%3));
			
			models.add(model);
		}
		
