@BeforeClass
  public static void startServerAndWorker() throws Exception {
    File serverWorkDir = temporaryFolder.newFolder();
    server = new Thread(() -> {
      try {
        final FuzzerServer fuzzerServer = new FuzzerServer(
            serverWorkDir.getAbsolutePath(), 8080, fileOps);
        fuzzerServer.start();
      } catch (Exception exception) {
        throw new RuntimeException(exception);
      }
    });
    server.start();

    final String clientJar = getClientJar();
    final List<String> command = Arrays.asList(
        "java", "-jar", clientJar);
    final ProcessBuilder pb =
        new ProcessBuilder()
            .command(command)
            .directory(temporaryFolder.getRoot());

    pb.redirectOutput(ProcessBuilder.Redirect.INHERIT);
    pb.redirectOutput(ProcessBuilder.Redirect.INHERIT);

    FileUtils.writeStringToFile(new File(temporaryFolder.getRoot(), "worker-name.txt"),
        WORKERNAME, StandardCharsets.UTF_8);

    worker = pb.start();

    int exceptionCount = 0;
    final int limit = 1000;
    File workerDirectory = Paths.get(serverWorkDir.getAbsolutePath(), "processing", WORKERNAME)
        .toFile();
    while (true) {
      Thread.sleep(10);
      if (workerDirectory.exists()) {
        break;
      }
      if (exceptionCount >= limit) {
        throw new RuntimeException("Problem starting worker and server");
      }
      exceptionCount++;
    }
    System.out.println("Got worker name after " + exceptionCount + " tries");
  }

@AfterClass
  public static void destroyWorker() {
    worker.destroy();
  }

