			new Socket("localhost", KinesisTestConfiguration.DEFAULT_KINESALITE_PORT).close();
			// Successful connection means local Kinesis is available
			isLocalKinesis = true;
		}
		catch (Exception e) {
			isLocalKinesis  = false;
		}
		assumeThat(isLocalKinesis).isTrue();
	}

