@AfterClass
  public static void exit() {
    ListResult<SysDict> listResult = queryTestDictList();
    assertTrue(listResult.getRecords().size() > 0);
    assertTrue(listResult.getTotal() > 0);
    for (SysDict sysDict : listResult.getRecords()) {
