      CommonDataTest.assertResponseSuccess(response);
    }

    //recheck
    ListResult listResult2 = queryTestDictList();
    assertEquals(listResult2.getTotal(), 0);
    assertEquals(listResult2.getRecords().size(), 0);
  }

