@After
    public void endTransaction() throws Exception {
        reporter.reset();
        dropCollection();
        assertThat(reporter.getSpans()).hasSize(1);
        assertThat(reporter.getFirstSpan().getNameAsString()).isEqualTo("testdb.testcollection.drop");
