@Before
		public void before() throws Exception {
			IFlightRecorderService service = getFlightRecorderService();
			SchemaVersion version = SchemaVersion.fromBeanVersion(service.getVersion());
			defaults = service.getDefaultEventOptions();
			mutable = defaults.emptyWithSameConstraints();

			if (versionRestriction != null) {
				Assume.assumeThat(version, is(versionRestriction));
			}

			IEventTypeID typeV1 = new EventTypeIDV1("http://www.example.org/bar/", "some/short/path");
			IEventTypeID typeV2 = new EventTypeIDV2("some.package.Event");
			if (version == SchemaVersion.V1) {
				periodicTypeID = jvm("java/statistics/threads");
				latencyTypeID = jvm("java/thread_sleep");
				unknownTypeID = typeV1;
				invalidTypeID = typeV2;
			} else {
				periodicTypeID = new EventTypeIDV2(JdkTypeIDs.THREAD_STATISTICS);
				latencyTypeID = new EventTypeIDV2(JdkTypeIDs.THREAD_SLEEP);
				unknownTypeID = typeV2;
				invalidTypeID = typeV1;
			}
		}

@Before
	public synchronized void mcTestCaseBefore() throws Exception {
		m_connectionDescriptor = getTestConnectionDescriptor();
		m_host = ConnectionToolkit.getHostName(m_connectionDescriptor.createJMXServiceURL());
		m_connection = new RJMXConnection(m_connectionDescriptor, createDefaultServerDesciptor(m_connectionDescriptor),
				null);
		m_connection.connect();
		m_connectionHandle = new DefaultConnectionHandle(m_connection, "Test", null);
		Assert.assertTrue(m_connectionHandle.isConnected());
	}

@After
	public synchronized void mcTestCaseAfter() throws Exception {
		if (m_connectionHandle != null) {
			m_connectionHandle.close();
			m_connectionHandle = null;
			if (m_connection != null) {
				m_connection.close();
				m_connection = null;
			}
		}
	}

