        .accountPermissionUpdate(accountPermissionJson, mutisignAccountAddress, mutisignAccountKey,
            blockingStubFull, new String[]{mutisignAccountKey}));
    PublicMethed.waitProduceNextBlock(blockingStubFull);
  }

