            .compile(SRC_DIR,
                     MODS_DIR,
                     "--module-source-path", SRC_DIR.toString());
        assertTrue(compiled);

        // javac --module-path mods -d classes Main.java
        compiled = CompilerUtils
            .compile(Paths.get(TEST_SRC, "Main.java"),
                     CLASSES_DIR,
                     "--module-path", MODS_DIR.toString(),
                     "--add-modules", "m1,m2");
        assertTrue(compiled);
    }

