                "lib", "modules");
        isExplodedBuild = Files.notExists(modulesPath);
        if (isExplodedBuild) {
            System.out.printf("%s doesn't exist.", modulesPath.toString());
            System.out.println();
            System.out.println("It is most probably an exploded build."
                    + " Skip non-default FileSystem testing.");
            return;
