            sleep();
            sleep();

            while (!edComp.isShowing()) {

            }

            new ExtTestCase.WaitFocus(edComp);

            ied.addActionListener(al);

            Component comp = KeyboardFocusManager.getCurrentKeyboardFocusManager().getPermanentFocusOwner();
            canRun = edComp == comp;
