            dispatchEvent(ke, edComp);

            sleep();
            System.err.println("Sending key released - space");
            ke = new KeyEvent(edComp, KeyEvent.KEY_RELEASED, System.currentTimeMillis(), 0, KeyEvent.VK_SPACE, (char) KeyEvent.VK_SPACE);
