            dispatchEvent(ke, edComp);
            sleep();

            System.err.println("Sending key released - enter");
            ke = new KeyEvent(edComp, KeyEvent.KEY_RELEASED, System.currentTimeMillis(), 0, KeyEvent.VK_ENTER, (char) KeyEvent.VK_ENTER);
            dispatchEvent(ke, edComp);

            sleep();

            idx++;

