			new AddressBasedLocation(program, null),
			new AddressBasedLocation(program, regRef2, ShowBlockName.ALWAYS),
			new AddressBasedLocation(program, addr("CODE:100")),
			new AddressBasedLocation(program, addr("C:100")),
