                        "IDataSet dataSet = builder" + NEW_LINE +
                        "    .table(\"FOLLOWER\")" + NEW_LINE +
                        "    .row()" + NEW_LINE +
                        "        .column(\"ID\", 1)" + NEW_LINE +
                        "        .column(\"USER_ID\", 1)" + NEW_LINE +
                        "        .column(\"FOLLOWER_ID\", 2)" + NEW_LINE +
