        // Delete permission:
        response = request("/nacos/v1/auth/permissions",
            Params.newParams()
                .appendParam("role", "role1")
                .appendParam("resource", "test1:*:*")
                .appendParam("action", "r")
                .appendParam("accessToken", accessToken)
                .done(),
