@BeforeClass
  public static void beforeClass() throws IOException {
    // get free local port
    ServerSocket serverSocket = new ServerSocket(0);
    port = serverSocket.getLocalPort();
    serverSocket.close();
    httpServer = HttpServer.create(new InetSocketAddress(port), 0);
    httpServer
        .createContext("/")
        .setHandler(
            httpExchange -> {
              try (final BufferedReader in =
                  new BufferedReader(
                      new InputStreamReader(
                          httpExchange.getRequestBody(), StandardCharsets.UTF_8))) {
                String line;
                while ((line = in.readLine()) != null) {
                  messages.add(line);
                }
              }
              httpExchange.sendResponseHeaders(HttpURLConnection.HTTP_OK, 0L);
              httpExchange.close();
              countDownLatch.countDown();
            });
    httpServer.start();
  }

@Before
  public void before() {
    messages.clear();
  }

@AfterClass
  public static void after() {
    httpServer.stop(0);
  }

@BeforeClass
  public static void beforeClass() throws Exception {
    final int parallelism = 1;

    Configuration config = new Configuration();
    // Avoid port collision in parallel tests
    config.setInteger(RestOptions.PORT, 0);
    config.setString(CheckpointingOptions.STATE_BACKEND, "filesystem");
    // It is necessary to configure the checkpoint directory for the state backend,
    // even though we only create savepoints in this test.
    config.setString(
        CheckpointingOptions.CHECKPOINTS_DIRECTORY,
        "file://" + tempFolder.getRoot().getAbsolutePath());
    // Checkpoints will go into a subdirectory of this directory
    config.setString(
        CheckpointingOptions.SAVEPOINT_DIRECTORY,
        "file://" + tempFolder.getRoot().getAbsolutePath());

    MiniClusterConfiguration clusterConfig =
        new MiniClusterConfiguration.Builder()
            .setConfiguration(config)
            .setNumTaskManagers(1)
            .setNumSlotsPerTaskManager(1)
            .build();

    flinkCluster = new MiniCluster(clusterConfig);
    flinkCluster.start();

    TestStreamEnvironment.setAsContext(flinkCluster, parallelism);
  }

