@BeforeClass
    public static void classSetUp() throws Exception {
        server = LibertyServerFactory
                        .getLibertyServer("com.ibm.ws.kernel.filemonitor.server");
        // install our user feature 
        server.installUserBundle(BUNDLE_NAME); // NO HYPHENS! NO ".jar" SUFFIX! 
        server.installUserFeature(FEATURE_NAME); // NO UNDERSCORES! NO ".mf" SUFFIX! 
        server.startServer();

        // Figure out where our test monitors are monitoring
        String foldereyecatcher = "-MONITORED FOLDER-";
        String line = server.waitForStringInLog(foldereyecatcher);
        assertNotNull("Our test feature should report the folder location we're monitoring.", line);
        int index = line.indexOf(foldereyecatcher) + foldereyecatcher.length();
        // We create the file objects but not files on disk
        monitoredFolder = new File(line.substring(index));

        String fileeyecatcher = "-MONITORED FILE-";
        line = server.waitForStringInLog(fileeyecatcher);
        assertNotNull("Our test feature should report the file location we're monitoring.", line);
        index = line.indexOf(fileeyecatcher) + fileeyecatcher.length();
        // We create the file objects but not files on disk
        monitoredFile = new File(line.substring(index));

        String nonexistentfileeyecatcher = "-NONEXISTENT FILE-";
        line = server.waitForStringInLog(nonexistentfileeyecatcher);
        assertNotNull("Our test feature should report the file location we're monitoring.", line);
        index = line.indexOf(nonexistentfileeyecatcher) + nonexistentfileeyecatcher.length();
        // We create the file objects but not files on disk
        nonexistentFile = new File(line.substring(index));

        String nonexistentfoldereyecatcher = "-NONEXISTENT FOLDER-";
        line = server.waitForStringInLog(nonexistentfoldereyecatcher);
        assertNotNull("Our test feature should report the folder location we're monitoring.", line);
        index = line.indexOf(nonexistentfoldereyecatcher) + nonexistentfoldereyecatcher.length();
        // We create the folder objects but not folders on disk
        nonexistentFolder = new File(line.substring(index));

    }

@After
    public void tearDown() throws Exception {
        // Clear up after any tests which may have deleted the monitored folder
        if (!monitoredFolder.exists()) {
            monitoredFolder.mkdirs();
            // Get rid of any notifications from reinstating the folder
            // This flush assumes that the monitor self monitor works 
            flushNotifications(monitorSelfMonitor);
        }

        // Get rid of any dangling notifications from tests, using the monitor most likely to catch something
        flushNotifications(recursiveMonitor);

    }

@BeforeClass
    public static void jmxSetUp() throws Exception {

        // Wait for the JMX server to be started 
        assertNotNull("The application 'IBMJMXConnectorREST' did not report it was started",
                      server.waitForStringInLog("CWWKT0016I.*IBMJMXConnectorREST"));
        // Wait for secure port to be ready
        assertNotNull("SSL port is not ready",
                      server.waitForStringInLog("CWWKO0219I.*ssl"));
        assertNotNull("The server is not ready to run a smarter planet",
                      server.waitForStringInLog("CWWKF0011I"));
        assertNotNull("The security service is not ready",
                      server.waitForStringInLog("CWWKS0008I"));

        trustEverything();

        Map<String, Object> fileTransferConfig = new HashMap<String, Object>();
        fileTransferConfig.put("jmx.remote.protocol.provider.pkgs", "com.ibm.ws.jmx.connector.client");
        fileTransferConfig.put(JMXConnector.CREDENTIALS, new String[] { "theUser", "thePassword" });
        fileTransferConfig.put(ClientProvider.DISABLE_HOSTNAME_VERIFICATION, true);
        fileTransferConfig.put(ClientProvider.READ_TIMEOUT, 2 * 60 * 1000);

        JMXServiceURL jmxServiceUrl = new JMXServiceURL("REST", server.getHostname(), server
                        .getHttpDefaultSecurePort(), "/IBMJMXConnectorREST");
        long connectTime = System.currentTimeMillis();
        try {
            jmxConnector = JMXConnectorFactory.connect(jmxServiceUrl, fileTransferConfig);

            MBeanServerConnection mbeanConn = jmxConnector.getMBeanServerConnection();
            final ObjectName name = new ObjectName(com.ibm.ws.kernel.filemonitor.FileNotificationMBean.INSTANCE_NAME);
            mbean = JMX.newMBeanProxy(mbeanConn, name,
                                      FileNotificationMBean.class);

            assertNotNull("We should have got access to the FileNotificationMBean", mbean);
        } catch (ConnectException e) {
            DateFormat formatter = new SimpleDateFormat("dd/MMM/yyyy HH:mm:ss:SSS z");
            String timestamp = formatter.format(new Date(connectTime));
            fail("Could not get a connection to the JMX server using URL " + jmxServiceUrl + ".\n Tried at " + timestamp + ".\n The exception was " + e);
        }

    }

@AfterClass
    public static void classTearDown() throws MalformedObjectNameException, NullPointerException, IOException {
        if (jmxConnector != null) {
            jmxConnector.close();
        }
    }

