    public void tearDown() {
        table.deactivate(cc);
        table.unsetSecurityService(securityServiceRef);
        table.unsetConfigurationAdmin(car);
        table.unsetFeatureAuthzTableService(fatsr);
        table = null;

        outputMgr.resetStreams();
    }

