        serverB.setJvmOptions(Arrays.asList("-Dhazelcast.group.name=" + rand,
                                            "-Dhazelcast.config=" + configLocation));

        serverA.startServer();

        // Since we initialize the JCache provider lazily, use an HTTP session on serverA before starting serverB,
