@SuppressWarnings("unchecked")
	@BeforeClass
	public static void fixClassPath() {
		URL ddrURL = null;
		try {
			ddrURL = new File(System.getProperty("java.home", ""), "lib/ddr/j9ddr.jar").toURI().toURL();
		} catch (MalformedURLException e) {
			// This can only happen with a typo in source code
			e.printStackTrace();
		}

		ClassLoader loader = ClassLoader.getSystemClassLoader();
		Class loaderClazz = loader.getClass();

		try {
			while (loaderClazz != null && !loaderClazz.getName().equals("java.net.URLClassLoader")) {
				loaderClazz = loaderClazz.getSuperclass();
			}

			if (loaderClazz == null) {
				throw new UnsupportedOperationException("Application class loader is not an instance of URLClassLoader.  Can not initialize J9DDR");
			}

			Method addURLMethod = loaderClazz.getDeclaredMethod("addURL", new Class[] {URL.class});
			addURLMethod.setAccessible(true);
			addURLMethod.invoke(loader, new Object[] {ddrURL});
		} catch (SecurityException e) {
			e.printStackTrace();
			throw new UnsupportedOperationException("Must enable suppressAccessChecks permission");
		} catch (NoSuchMethodException e) {
			e.printStackTrace();
		} catch (IllegalArgumentException e) {
			e.printStackTrace();
		} catch (IllegalAccessException e) {
			throw new UnsupportedOperationException("Must enable suppressAccessChecks permission");
		} catch (InvocationTargetException e) {
			e.printStackTrace();
		}
	}

@BeforeClass
	public static void beforeClass() {

		try {
			String coreFileName = System.getProperty("ddr.core.file.name");
			if (coreFileName == null) {
				fail("Did not specify core file name with -Dddr.core.file.name");
			}

			ICore core = CoreReader.readCoreFile(coreFileName);

			List<IAddressSpace> addressSpaces = new ArrayList<IAddressSpace>(core.getAddressSpaces());

			for (IAddressSpace thisAS : addressSpaces) {
				for (IProcess thisProc : thisAS.getProcesses()) {
					try {
						vmData = VMDataFactory.getVMData(thisProc);
						return;
					} catch (IOException ex) {
						//This happens if we can't find a JVM or a blob. Keep looking
					}
				}
			}

			fail("Couldn't initialize VMData");
		} catch (FileNotFoundException e) {
			fail("Could not initialize VMData: " + e.getMessage());
		} catch (IOException e) {
			fail("Could not initialize VMData: " + e.getMessage());
		}
	}

