@BeforeSuite
    public void setUp() throws Exception {
        KeyStore keyStore = KeyStore.getInstance("PKCS12");

        keyStore.load(getClass().getClassLoader().getResourceAsStream("test-keystore.pfx"), PASSWORD);

        {
            Key clientPrivateKey = keyStore.getKey(CLIENT_ALIAS, PASSWORD);
            if (clientPrivateKey instanceof PrivateKey) {
                clientCertificate = (X509Certificate) keyStore.getCertificate(CLIENT_ALIAS);
                clientCertificateBytes = clientCertificate.getEncoded();

                PublicKey clientPublicKey = clientCertificate.getPublicKey();
                clientKeyPair = new KeyPair(clientPublicKey, (PrivateKey) clientPrivateKey);
            }
        }

        {
            Key clientPrivateKey4096 = keyStore.getKey(CLIENT_ALIAS_4096, PASSWORD);
            if (clientPrivateKey4096 instanceof PrivateKey) {
                clientCertificate4096 = (X509Certificate) keyStore.getCertificate(CLIENT_ALIAS_4096);
                clientCertificateBytes4096 = clientCertificate4096.getEncoded();

                PublicKey clientPublicKey = clientCertificate4096.getPublicKey();
                clientKeyPair4096 = new KeyPair(clientPublicKey, (PrivateKey) clientPrivateKey4096);
            }
        }

        {
            Key serverPrivateKey = keyStore.getKey(SERVER_ALIAS, PASSWORD);
            if (serverPrivateKey instanceof PrivateKey) {
                serverCertificate = (X509Certificate) keyStore.getCertificate(SERVER_ALIAS);
                serverCertificateBytes = serverCertificate.getEncoded();

                PublicKey serverPublicKey = serverCertificate.getPublicKey();
                serverKeyPair = new KeyPair(serverPublicKey, (PrivateKey) serverPrivateKey);
            }
        }

        {
            Key serverPrivateKey4096 = keyStore.getKey(SERVER_ALIAS_4096, PASSWORD);
            if (serverPrivateKey4096 instanceof PrivateKey) {
                serverCertificate4096 = (X509Certificate) keyStore.getCertificate(SERVER_ALIAS_4096);
                serverCertificateBytes4096 = serverCertificate4096.getEncoded();

                PublicKey serverPublicKey = serverCertificate4096.getPublicKey();
                serverKeyPair4096 = new KeyPair(serverPublicKey, (PrivateKey) serverPrivateKey4096);
            }
        }

        serverCertificateManager = new TestCertificateManager(
            serverKeyPair,
            serverCertificate
        );

        serverCertificateValidator = new TestServerCertificateValidator(clientCertificate);
    }

@BeforeSuite
    public void setUpClientServer() throws Exception {
        super.setUp();

        int tcpBindPort = getTcpBindPort();
        int httpsBindPort = getHttpsBindPort();

        KeyPair httpsKeyPair = SelfSignedCertificateGenerator.generateRsaKeyPair(2048);

        X509Certificate httpsCertificate = new SelfSignedHttpsCertificateBuilder(httpsKeyPair)
            .setCommonName("localhost")
            .build();

        List<String> bindAddresses = newArrayList();
        bindAddresses.add("localhost");

        List<String> hostnames = newArrayList();
        hostnames.add("localhost");

        Set<EndpointConfiguration> endpointConfigurations = new LinkedHashSet<>();

        for (String bindAddress : bindAddresses) {
            for (String hostname : hostnames) {
                EndpointConfiguration.Builder base = EndpointConfiguration.newBuilder()
                    .setBindAddress(bindAddress)
                    .setHostname(hostname)
                    .setPath("/test")
                    .setCertificate(serverCertificate)
                    .addTokenPolicies(USER_TOKEN_POLICY_ANONYMOUS);

                // TCP Transport Endpoints
                endpointConfigurations.add(
                    base.copy()
                        .setBindPort(tcpBindPort)
                        .setSecurityPolicy(SecurityPolicy.None)
                        .setSecurityMode(MessageSecurityMode.None)
                        .setTransportProfile(TransportProfile.TCP_UASC_UABINARY)
                        .build()
                );

                endpointConfigurations.add(
                    base.copy()
                        .setBindPort(tcpBindPort)
                        .setSecurityPolicy(SecurityPolicy.Basic256Sha256)
                        .setSecurityMode(MessageSecurityMode.SignAndEncrypt)
                        .setTransportProfile(TransportProfile.TCP_UASC_UABINARY)
                        .build()
                );

                // HTTPS Transport Endpoints
                endpointConfigurations.add(
                    base.copy()
                        .setBindPort(httpsBindPort)
                        .setSecurityPolicy(SecurityPolicy.None)
                        .setSecurityMode(MessageSecurityMode.None)
                        .setTransportProfile(TransportProfile.HTTPS_UABINARY)
                        .build()
                );

                endpointConfigurations.add(
                    base.copy()
                        .setBindPort(httpsBindPort)
                        .setSecurityPolicy(SecurityPolicy.Basic256Sha256)
                        .setSecurityMode(MessageSecurityMode.SignAndEncrypt)
                        .setTransportProfile(TransportProfile.HTTPS_UABINARY)
                        .build()
                );
            }
        }

        UaStackServerConfig serverConfig = configureServer(
            UaStackServerConfig.builder()
                .setEndpoints(endpointConfigurations)
                .setCertificateManager(serverCertificateManager)
                .setCertificateValidator(serverCertificateValidator)
                .setHttpsKeyPair(httpsKeyPair)
                .setHttpsCertificate(httpsCertificate)
        ).build();

        stackServer = new UaStackServer(serverConfig);
        stackServer.startup().get();

        String discoveryUrl = getDiscoveryUrl();

        EndpointDescription endpoint = selectEndpoint(
            DiscoveryClient.getEndpoints(discoveryUrl)
                .thenApply(endpoints -> {
                    endpoints.forEach(e ->
                        logger.info("discovered endpoint: {}", e.getEndpointUrl()));

                    return endpoints;
                })
                .get()
        );

        UaStackClientConfig clientConfig = configureClient(
            UaStackClientConfig.builder()
                .setEndpoint(endpoint)
                .setKeyPair(clientKeyPair)
                .setCertificate(clientCertificate)
                .setRequestTimeout(uint(5000))
        ).build();

        stackClient = UaStackClient.create(clientConfig);
        stackClient.connect().get();
    }

@AfterSuite
    public void tearDownClientServer() throws Exception {
        stackClient.disconnect().get();
        stackServer.shutdown().get();
    }

