@Before
    public void before() {
        if (webClient_ != null && webClient_.getJavaScriptEngine() instanceof JavaScriptEngine) {
            assertTrue(getJavaScriptThreads().isEmpty());
        }
    }

@Override
    @After
    public void releaseResources() {
        super.releaseResources();
        boolean rhino = false;
        if (webClient_ != null) {
            rhino = webClient_.getJavaScriptEngine() instanceof JavaScriptEngine;
            webClient_.close();
            webClient_.getCookieManager().clearCookies();
        }
        webClient_ = null;

        if (rhino) {
            final List<Thread> jsThreads = getJavaScriptThreads();
            assertEquals(0, jsThreads.size());

            // collect stack traces
            // caution: the threads may terminate after the threads have been returned by getJavaScriptThreads()
            // and before stack traces are retrieved
            if (jsThreads.size() > 0) {
                final Map<String, StackTraceElement[]> stackTraces = new HashMap<>();
                for (final Thread t : jsThreads) {
                    final StackTraceElement[] elts = t.getStackTrace();
                    if (elts != null) {
                        stackTraces.put(t.getName(), elts);
                    }
                }

                if (!stackTraces.isEmpty()) {
                    System.err.println("JS threads still running:");
                    for (final Map.Entry<String, StackTraceElement[]> entry : stackTraces.entrySet()) {
                        System.err.println("Thread: " + entry.getKey());
                        final StackTraceElement[] elts = entry.getValue();
                        for (final StackTraceElement elt : elts) {
                            System.err.println(elt);
                        }
                    }
                    throw new RuntimeException("JS threads are still running: " + jsThreads.size());
                }
            }
        }
    }

@AfterClass
    public static void shutDownAll() throws Exception {
        for (final WebDriver driver : WEB_DRIVERS_.values()) {
            driver.quit();
        }
        WEB_DRIVERS_.clear();

        shutDownRealBrowsers();

        stopWebServers();
    }

@Before
    public void beforeTest() throws InterruptedException {
        if (!isWebClientCached()) {
            if (!getJavaScriptThreads().isEmpty()) {
                Thread.sleep(200);
            }
            assertTrue("There are already JS threads running before the test", getJavaScriptThreads().isEmpty());
        }
    }

@After
    @Override
    public void releaseResources() {
        final List<String> unhandledAlerts = new ArrayList<>();
        if (webDriver_ != null) {
            UnhandledAlertException ex = null;
            do {
                ex = null;
                try {
                    // getTitle will do an implicit check for open alerts
                    webDriver_.getTitle();
                }
                catch (final NoSuchWindowException e) {
                    // ignore
                }
                catch (final UnhandledAlertException e) {
                    ex = e;
                    unhandledAlerts.add(e.getMessage());
                }
            }
            while (ex != null);
        }

        super.releaseResources();

        if (!isWebClientCached()) {
            boolean rhino = false;
            if (webDriver_ != null) {
                try {
                    rhino = getWebWindowOf(webDriver_).getWebClient().getJavaScriptEngine() instanceof JavaScriptEngine;
                }
                catch (final Exception e) {
                    throw new RuntimeException(e);
                }
                webDriver_.quit();
                webDriver_ = null;
            }
            if (rhino) {
                assertTrue("There are still JS threads running after the test", getJavaScriptThreads().isEmpty());
            }
        }

        if (useRealBrowser()) {
            synchronized (WEB_DRIVERS_REAL_BROWSERS) {
                final WebDriver driver = WEB_DRIVERS_REAL_BROWSERS.get(getBrowserVersion());
                if (driver != null) {
                    try {
                        final String currentWindow = driver.getWindowHandle();

                        final Set<String> handles = driver.getWindowHandles();
                        // close all windows except the current one
                        handles.remove(currentWindow);

                        if (handles.size() > 0) {
                            for (final String handle : handles) {
                                try {
                                    driver.switchTo().window(handle);
                                    driver.close();
                                }
                                catch (final NoSuchWindowException e) {
                                    LOG.error("Error switching to browser window; quit browser.", e);
                                    WEB_DRIVERS_REAL_BROWSERS.remove(getBrowserVersion());
                                    WEB_DRIVERS_REAL_BROWSERS_USAGE_COUNT.remove(getBrowserVersion());
                                    driver.quit();
                                    return;
                                }
                            }

                            // we have to force WebDriver to treat the remaining window
                            // as the one we like to work with from now on
                            // looks like a web driver issue to me (version 2.47.2)
                            driver.switchTo().window(currentWindow);
                        }

                        driver.manage().deleteAllCookies();

                        // in the remaining window, load a blank page
                        driver.get("about:blank");
                    }
                    catch (final WebDriverException e) {
                        shutDownRealBrowsers();
                    }
                }
            }
        }
        assertTrue("There are still unhandled alerts: " + String.join("; ", unhandledAlerts),
                        unhandledAlerts.isEmpty());
    }

