                    if (directEventTypes != null) {
                      Map<String, String> customEventType =
                          (Map<String, String>) directEventTypes.get(eventName);
                      if (customEventType != null) {
                        return customEventType.get("registrationName");
                      }
                    }
                    return eventName;
                  }
